DROP TABLE IF EXISTS `customer_balances`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `customer_balances` (
  `AccMain` varchar(11) COLLATE utf8mb4_unicode_ci NOT NULL,
  `AccSub` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '000',
  `AgedBalance1` decimal(18,3) NOT NULL DEFAULT 0.000,
  `AgedBalance2` decimal(18,3) NOT NULL DEFAULT 0.000,
  `AgedBalance3` decimal(18,3) NOT NULL DEFAULT 0.000,
  `AgedBalance4` decimal(18,3) NOT NULL DEFAULT 0.000,
  `AgedBalance5` decimal(18,3) NOT NULL DEFAULT 0.000,
  `AgedBalance6` decimal(18,3) NOT NULL DEFAULT 0.000,
  `LastEditedBy` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`AccMain`),
  KEY `customer_balances_lasteditedby_foreign` (`LastEditedBy`),
  CONSTRAINT `customer_balances_accmain_foreign` FOREIGN KEY (`AccMain`) REFERENCES `customers` (`acc_main`),
  CONSTRAINT `customer_balances_lasteditedby_foreign` FOREIGN KEY (`LastEditedBy`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
